function restartGame() { goOverlay.style.display = 'none'; gameOverFlag = false; player.score = 0; currentLevel = 1; initClouds(); setupLevel(currentLevel); gameState = 'COUNTDOWN'; countdownTimer = 3; lastCountdownUpdate = performance.now(); }

function initClouds() { clouds = []; for (let i = 0; i < 6; i++) { clouds.push(new Cloud(i * 200 + Math.random() * 100, 30 + Math.random() * 80, 0.3 + Math.random() * 0.5)); } }

function setupLevel(n) { currentLevelObj = new Level(n); currentLevelObj.pop(); player.x = 60; player.y = (currentLevelObj.height - 4) * TILE_SIZE; player.vx = 0; player.vy = 0; player.grounded = true; camera.x = 0; }

function collide(x, y, w, h) {
    const lv = currentLevelObj;
    const tl = Math.floor(x / TILE_SIZE), tr = Math.floor((x + w) / TILE_SIZE);
    const tt = Math.floor(y / TILE_SIZE), tb = Math.floor((y + h) / TILE_SIZE);
    for (let yy = tt; yy <= tb; yy++) {
        for (let xx = tl; xx <= tr; xx++) {
            if (yy >= 0 && yy < lv.height && xx >= 0 && xx < lv.width && lv.data[yy][xx] === 1) return true;
        }
    }
    return false;
}

Level.prototype.sX = function() { for (let tries = 0; tries < 20; tries++) { const rx = 2 + ~~(Math.random() * (this.width - 4)); if (this.data[this.height - 3][rx] === 0) return rx; } return -1; };

