function initClouds(){clouds=[];for(let i=0;i<8;i++){clouds.push(new Cloud(Math.random()*VIEWPORT_W,20+Math.random()*60,0.2+Math.random()*0.5));}}

function setupLevel(num){
  currentLevelObj=new Level(num);
  currentLevelObj.pop();
  player.x=TILE_SIZE*2;
  player.y=(currentLevelObj.height-3)*TILE_SIZE;
  player.vx=0;player.vy=0;
}

function collide(x,y,w,h){
  const t=Math.floor(y/TILE_SIZE),b=Math.floor((y+h-1)/TILE_SIZE);
  const l=Math.floor(x/TILE_SIZE),r=Math.floor((x+w-1)/TILE_SIZE);
  for(let ty=t;ty<=b;ty++)for(let tx=l;tx<=r;tx++){
    if(ty<0||ty>=currentLevelObj.height||tx<0||tx>=currentLevelObj.width)return false;
    if(currentLevelObj.data[ty][tx]===1)return true;
  }
  return false;
}

function startGame(){if(!sound.ctx)sound.init();initClouds();setupLevel(currentLevel);gameState='COUNTDOWN';countdownTimer=3;lastCountdownUpdate=performance.now();}

