const vm = require("vm");
const fs = require("fs");

const html = fs.readFileSync("manic_miner.html", "utf8");
const match = html.match(/<script\b[^>]*>([\s\S]*?)<\/script>/gi);
if (!match) { console.log("No script found"); process.exit(1); }
const scriptContent = match[0].replace(/<script\b[^>]*>/i, "").replace(/<\/script>/i, "");

// Only catch SyntaxError, let ReferenceError pass
try {
  vm.runInNewContext(scriptContent, {});
  console.log("OK");
} catch(e) {
  if (e.name === "SyntaxError") {
    console.log("SYNTAX ERROR:", e.message);
    // Find the exact line using node --check
    const tmp = fs.mkdtempSync(require('os').tmpdir() + '/');
    fs.writeFileSync(tmp + '/test.js', scriptContent);
    try {
      require('child_process').execSync('node --check ' + tmp + '/test.js', { encoding: 'utf8' });
    } catch(ex) {
      console.log("node --check output:", ex.stderr);
    }
    // Clean up
    fs.rmSync(tmp, { recursive: true });
  } else {
    console.log("RUNTIME ERROR:", e.name + ": " + e.message);
    console.log("(Runtime errors are expected since we have no browser env)");
  }
}

