  console.log("SYNTAX ERROR:");
  console.log(e.stderr);
  fs.rmSync(tmp, { recursive: true });
  process.exit(1);
}

// Find all function declarations
const lines = scriptContent.split("\n");
const funcPattern = /function\s+(\w+)/g;
const declaredFunctions = new Set();
for (const line of lines) {
  let m;
  while ((m = funcPattern.exec(line)) !== null) {
    declaredFunctions.add(m[1]);
  }
}

// Find all function calls (pattern: word followed by ( )
const callsPattern = /(\w+)\s*\(/g;
const calledFunctions = new Set();
for (const line of lines) {
  let m;
  while ((m = callsPattern.exec(line)) !== null) {
    const name = m[1];
    if (!declaredFunctions.has(name)) {
      calledFunctions.add(name);
    }
  }
}

console.log("Undeclared functions that are called:");
for (const name of calledFunctions) {
  console.log("  - " + name);
}

fs.rmSync(tmp, { recursive: true });

