let clouds = [];

function initClouds() {
    clouds = [];
    for (let i = 0; i < 8; i++) {
        clouds.push(new Cloud(Math.random() * 2000 - 500, Math.random() * 150 + 20, 0.3 + Math.random() * 0.5));
    }
}

function setupLevel(level) {
    currentLevel = level;
    currentLevelObj = new Level(level);
    currentLevelObj.pop();
    player.x = TILE_SIZE * 2;
    player.y = (currentLevelObj.height - 4) * TILE_SIZE;
    player.vx = 0;
    player.vy = 0;
    player.grounded = false;
}

function collide(x, y, w, h) {
    const left = Math.floor(x / TILE_SIZE);
    const right = Math.floor((x + w) / TILE_SIZE);
    const top = Math.floor(y / TILE_SIZE);
    const bottom = Math.floor((y + h) / TILE_SIZE);
    if (left < 0 || right >= currentLevelObj.width || top < 0 || bottom >= currentLevelObj.height) return true;
    for (let ty = top; ty <= bottom; ty++) {
        for (let tx = left; tx <= right; tx++) {
            if (currentLevelObj.data[ty][tx] === 1) return true;
        }
    }
    return false;
}

let currentLevel = 1;

