const l = c.split('\n');
let bal = 0;
for (let i = 0; i < l.length; i++) {
  const line = l[i];
  const stripped = line.replace(/'[^']*'/g, '').replace(/"[^"]*"/g, '').replace(/`[^`]*`/g, '');
  let opens = 0, closes = 0;
  for (const ch of stripped) { if (ch === '{') opens++; if (ch === '}') closes++; }
  bal += opens - closes;
  if (i >= 55 && i <= 70) {
    console.log('L' + (i+1) + ': +' + opens + ' -' + closes + ' bal=' + bal + ' | ' + line.substring(0, 100));
  }
}
console.log('Final balance:', bal);

